    function new(string name = "axi_cdma_coverage",uvm_component parent);
       super.new(name,parent);
       cvrg = new();
    endfunction


    extern function void build_phase (uvm_phase phase);
    extern function void start_of_simulation_phase(uvm_phase phase);
    extern task main_phase (uvm_phase phase);
    extern task get_reg_module_pkt                ();
    extern task get_dma_module_pkt                ();
    extern task get_sg_engine_pkt                 ();
    extern task get_intrrupt_out_pkt              ();
    extern task get_mirrored_values               (axi_cdma_axi_master_seq_item mas_seq_item);
    extern task get_descriptor_values             (axi_cdma_axi_slave_seq_item slv_seq_item);
endclass : axi_cdma_coverage


function void axi_cdma_coverage::build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (!uvm_config_db #(axi_cdma_config_obj) :: get (null , "*" , "axi_cdma_config_obj" , obj))
     `uvm_fatal("CDMA_COVERAGE::build_phase","Config_obj get Failure")
     m_af = new[obj.no_of_masters];
     s_af = new[obj.no_of_slaves];

     foreach(m_af[i])
     m_af[i]=new($sformatf("m_af[%d]",i),this);
     foreach(s_af[i])
     s_af[i]=new($sformatf("s_af[%d]",i),this);
     i_af = new ("i_af",this);
     `uvm_info ("CDMA_COVERAGE::build_phase" , phase.get_name() , UVM_NONE)

     for(int i=0;i<obj.no_of_masters;i++)
       mas_seq_item[i] = axi_cdma_axi_master_seq_item :: type_id :: create($sformatf("mas_seq_item[%0d]",i));
     for(int i=0;i<obj.no_of_slaves;i++)
       slv_seq_item[i] = axi_cdma_axi_slave_seq_item :: type_id :: create($sformatf("slv_seq_item[%0d]",i));

       intr_seq_item = axi_cdma_interrupt_seq_item :: type_id :: create("intr_seq_item");

       desc_seq_item = axi_cdma_descriptor_seq_item :: type_id :: create("desc_seq_item"); 
endfunction : build_phase

  function void axi_cdma_coverage :: start_of_simulation_phase(uvm_phase phase);
    `uvm_info ("cdma_scb::start_of_simulation" , phase.get_name() , UVM_NONE)
     if(!uvm_config_db #(cdma_reg_block) :: get (this, "","cdma_reg_block" , m_reg_block))
       `uvm_fatal("cdma_scb::start_of_simulation", "cdma_reg_block get Failure")

  endfunction : start_of_simulation_phase


task axi_cdma_coverage::main_phase(uvm_phase phase);
   int no_of_get;
  `uvm_info("CDMA_COVERAGE::main_phase","Main Phase of CVRG",UVM_NONE);
     fork 
       get_reg_module_pkt();
       get_dma_module_pkt();
       get_sg_engine_pkt();
       get_intrrupt_out_pkt();
     join

endtask :main_phase

task axi_cdma_coverage::get_reg_module_pkt;
    axi_cdma_axi_master_seq_item m_seq_item,m_copied_packet;
    int no_of_get;
    `uvm_info ("CDMA_COVERAGE::get_reg_module_pkt" , "Getting Register Module Packets" , UVM_NONE)
     forever begin
      `uvm_info ("CDMA_COVERAGE::get_reg_module_pkt" , $sformatf("NO_OF_REGISTER_Pkt_GOT_BEFORE =%0d",no_of_get) , UVM_NONE)
       m_af[0].get(mas_seq_item[0]);
       no_of_get++;
      `uvm_info ("CDMA_COVERAGE::get_reg_module_pkt" , $sformatf("NO_OF_REGISTER_Pkt_GOT =%0d",no_of_get) , UVM_DEBUG)
       get_mirrored_values(mas_seq_item[0]);
       cvrg.sample();
     end
endtask : get_reg_module_pkt

task axi_cdma_coverage::get_dma_module_pkt;

    `uvm_info ("CDMA_COVERAGE::get_dma_module_pkt" , "Getting DMA Module Packets" , UVM_NONE)
     forever begin
       s_af[0].get(slv_seq_item[0]);
       if(slv_seq_item[0].operation==READ) begin
         foreach(slv_seq_item[0].rresp[i])
           if(slv_seq_item[0].rresp[i]==DECERR)
             dma_dec_err = 1;
           else if(slv_seq_item[0].rresp[i]==SLVERR)
             dma_slv_err = 1;
       end
       cvrg.sample();
       dma_dec_err = 0;
       dma_slv_err = 0;
     end
endtask : get_dma_module_pkt

task axi_cdma_coverage::get_sg_engine_pkt;

    `uvm_info ("CDMA_COVERAGE::get_sg_engine_pkt" , "Getting SG Engine Packets" , UVM_NONE)
     forever begin
       s_af[1].get(slv_seq_item[1]);
       get_descriptor_values(slv_seq_item[1]);
       if(slv_seq_item[1].operation==READ) begin
         foreach(slv_seq_item[1].rresp[i])
           if(slv_seq_item[1].rresp[i]==DECERR)
             sg_dec_err = 1;
           else if(slv_seq_item[0].rresp[i]==SLVERR)
             sg_slv_err = 1;
       end
       cvrg.sample();
       sg_dec_err = 0;
       sg_slv_err = 0;
     end
endtask : get_sg_engine_pkt

task axi_cdma_coverage::get_intrrupt_out_pkt;

    `uvm_info ("CDMA_COVERAGE::get_intrrupt_out_pkt" , "Getting Interrupt Out Packets" , UVM_NONE)
     forever begin
       i_af.get(intr_seq_item);
       cvrg.sample();
     end
endtask : get_intrrupt_out_pkt


task axi_cdma_coverage :: get_mirrored_values(axi_cdma_axi_master_seq_item mas_seq_item);
    `uvm_info ("CDMA_COVERAGE::get_mirror_value" , "Get the Mirrored values of RAL" , UVM_NONE)
    if(mas_seq_item.operation==WRITE ) begin
      case(mas_seq_item.awaddr)
        CNTRL_REG_ADDR    : CR                     = m_reg_block.CDMA_CR_h.get_mirrored_value();

        STATUS_REG_ADDR   : SR                     = m_reg_block.CDMA_SR_h.get_mirrored_value();

        CURDESC_LSB_ADDR  : CURDESC_PNTR  [31:0]   = m_reg_block.CURDESC_PNTR_h.get_mirrored_value();

        CURDESC_MSB_ADDR  : CURDESC_PNTR  [63:32]  = m_reg_block.CURDESC_PNTR_MSB_h.get_mirrored_value();

        TAILDESC_LSB_ADDR : TAILDESC_PNTR [31:0]   = m_reg_block.TAILDESC_PNTR_h.get_mirrored_value();

        TAILDESC_MSB_ADDR : TAILDESC_PNTR [63:32]  = m_reg_block.TAILDESC_PNTR_MSB_h.get_mirrored_value();

        SA_LSB_ADDR       : SA [31:0]              = m_reg_block.SA_h.get_mirrored_value();

        SA_MSB_ADDR       : SA [63:32]             = m_reg_block.SA_MSB_h.get_mirrored_value();

        DA_LSB_ADDR       : DA [31:0]              = m_reg_block.DA_h.get_mirrored_value();

        DA_MSB_ADDR       : DA [63:32]             = m_reg_block.DA_MSB_h.get_mirrored_value();

        BTT_ADDR          : BTT                    = m_reg_block.BTT_h.get_mirrored_value();
      endcase
     end else if(mas_seq_item.operation== READ ) begin
             `uvm_info ("CDMA_COVERAGE::get_mirror_value" , "While Reading the Status Register" , UVM_NONE)
      case(mas_seq_item.araddr)

        STATUS_REG_ADDR   :  begin 
                               SR = m_reg_block.CDMA_SR_h.get_mirrored_value();
                              `uvm_info ("CDMA_COVERAGE::get_mirror_value" , $sformatf("SR[1]=%b",SR[1]) , UVM_DEBUG)
                             end
        
      endcase
     end

  endtask : get_mirrored_values


  task axi_cdma_coverage :: get_descriptor_values(axi_cdma_axi_slave_seq_item slv_seq_item);
    `uvm_info ("CDMA_COVERAGE::get_mirror_value" , "Get the Mirrored values of RAL" , UVM_NONE)
    if(slv_seq_item.operation==READ ) begin
      desc_seq_item.next_desc_pntr = {slv_seq_item.rdata[1],slv_seq_item.rdata[0]};        
      desc_seq_item.source_addr    = {slv_seq_item.rdata[3],slv_seq_item.rdata[2]};        
      desc_seq_item.dest_addr      = {slv_seq_item.rdata[5],slv_seq_item.rdata[4]};        
      desc_seq_item.control_word   = slv_seq_item.rdata[6];
    end

  endtask : get_descriptor_values




